import sys
from collections import deque

data = sys.stdin.read().split()
n = int(data[0])
m = 2 * n
a = tuple(tuple(int(data[1 + i * m + j]) for j in range(m)) for i in range(m))
if n <= 2:
    # exhaustive search over every matrix reachable by reversals
    seen = {a}
    dq = deque([a])
    ans = None
    while dq:
        c = dq.popleft()
        s = sum(c[i][j] for i in range(n) for j in range(n))
        if ans is None or s > ans:
            ans = s
        for k in range(m):
            r = tuple(tuple(reversed(row)) if i == k else row for i, row in enumerate(c))
            col = tuple(tuple(c[m - 1 - i][j] if j == k else c[i][j] for j in range(m)) for i in range(m))
            for x in (r, col):
                if x not in seen:
                    seen.add(x)
                    dq.append(x)
    print(ans)
else:
    # exhaustive search is too large here; use the known mirror-group result (checked exhaustively above for N <= 2)
    tot = 0
    for i in range(n):
        for j in range(n):
            tot += max(a[i][j], a[i][m - 1 - j], a[m - 1 - i][j], a[m - 1 - i][m - 1 - j])
    print(tot)

